const $=s=>document.querySelector(s),mean=a=>a.reduce((s,x)=>s+x,0)/a.length,q=(a,p)=>{let b=[...a].sort((a,b)=>a-b),i=(b.length-1)*p,l=Math.floor(i);return b[l]+(b[Math.ceil(i)]-b[l])*(i-l)},f=x=>Number(x).toFixed(2);let DATA;
const labels={studytime:['Under 2h','2–5h','5–10h','Over 10h'],higher:['No plans','Plans higher education']};
function table(headers,rows){return '<div class="tablewrap"><table><thead><tr>'+headers.map(h=>`<th>${h}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>`<td>${x}</td>`).join('')+'</tr>').join('')+'</tbody></table></div>'}
const svg=(content)=>`<svg viewBox="0 0 520 280" role="img">${content}</svg>`;const y=v=>230-v*10;function axes(){return [0,5,10,15,20].map(v=>`<line x1="45" x2="500" y1="${y(v)}" y2="${y(v)}" stroke="#e4eae3"/><text x="20" y="${y(v)+4}">${v}</text>`).join('')+'<text x="45" y="16">Final grade / 20</text>'}
function card(title,chart,note,headers,rows){return `<article class="card"><div class="eyebrow">RESEARCH QUESTION</div><h3>${title}</h3>${chart}<p>${note}</p><details><summary>View chart data</summary>${table(headers,rows)}</details></article>`}
function box(d,col,title,note){let keys=col==='studytime'?[1,2,3,4]:['no','yes'],rows=[],s=axes();keys.forEach((k,i)=>{let a=d.filter(r=>r[col]==k).map(r=>r.G3),x=90+i*(380/keys.length);if(!a.length)return;let lo=q(a,.25),hi=q(a,.75),med=q(a,.5),wlo=Math.min(...a.filter(v=>v>=lo-1.5*(hi-lo))),whi=Math.max(...a.filter(v=>v<=hi+1.5*(hi-lo))),lab=labels[col][i];s+=`<g><title>${lab}: n=${a.length}, median=${med}</title><line x1="${x}" x2="${x}" y1="${y(wlo)}" y2="${y(whi)}" stroke="#23765b"/><rect x="${x-24}" y="${y(hi)}" width="48" height="${Math.max(1,(hi-lo)*10)}" fill="#b5d8bf" stroke="#23765b"/><line x1="${x-24}" x2="${x+24}" y1="${y(med)}" y2="${y(med)}" stroke="#16382f" stroke-width="3"/>${a.filter(v=>v<wlo||v>whi).map(v=>`<circle cx="${x}" cy="${y(v)}" r="2" fill="#23765b"/>`).join('')}<text x="${x}" y="252" text-anchor="middle">${lab}</text><text x="${x}" y="270" text-anchor="middle">n=${a.length}</text></g>`;rows.push([lab,a.length,f(med),f(lo),f(hi)])});return card(title,svg(s),note,['Group','n','Median','Q1','Q3'],rows)}
function comparison(d,cols,title,note){let groups=[];for(let col of cols)for(let k of ['no','yes']){let a=d.filter(r=>r[col]===k).map(r=>r.G3);if(!a.length)continue;let m=mean(a),sd=a.length>1?Math.sqrt(a.reduce((s,v)=>s+(v-m)**2,0)/(a.length-1)):0,stored=DATA.groups[col]?.find(g=>g.label===(col==='internet'?(k==='yes'?'Internet at home':'No home internet'):col==='schoolsup'?(k==='yes'?'Receives school support':'No school support'):(k==='yes'?'Family support':'No family support')));let t=DATA.t_critical[a.length]||0;groups.push({label:(col==='internet'?'Internet':col==='schoolsup'?'School support':'Family support')+': '+k,n:a.length,m,low:$('#school').value==='all'&&stored?stored.low:m-t*sd/Math.sqrt(a.length),high:$('#school').value==='all'&&stored?stored.high:m+t*sd/Math.sqrt(a.length)})}let s=axes();groups.forEach((g,i)=>{let x=100+i*(370/groups.length);s+=`<g><title>${g.label}: mean ${f(g.m)}, 95% CI ${f(g.low)}–${f(g.high)}, n=${g.n}</title><line x1="${x}" x2="${x}" y1="${y(g.low)}" y2="${y(g.high)}" stroke="#23765b" stroke-width="2"/><circle cx="${x}" cy="${y(g.m)}" r="6" fill="#23765b"/><text x="${x}" y="251" text-anchor="middle" style="font-size:9px">${g.label}</text><text x="${x}" y="269" text-anchor="middle">n=${g.n}</text></g>`});return card(title,svg(s),note,['Group','n','Mean','CI low','CI high'],groups.map(g=>[g.label,g.n,f(g.m),f(g.low),f(g.high)]))}
function scatter(d){let max=Math.max(1,...d.map(r=>r.absences)),s=axes();d.forEach((r,i)=>s+=`<circle cx="${45+r.absences/max*445+(i%5-2)*.8}" cy="${y(r.G3)+(i%3-1)*.8}" r="3" fill="#23765b" opacity=".3"><title>Absences: ${r.absences}; grade: ${r.G3}</title></circle>`);s+=`<text x="45" y="254">0</text><text x="480" y="254">${max}</text><text x="220" y="275">Number of absences</text>`;return card('02 · How are absences associated with grades?',svg(s),'Slight deterministic jitter reveals overlapping observations. Zero grades are retained. A pattern cannot establish that absence causes lower grades.',['Absences','n','Mean grade'],[...new Set(d.map(r=>r.absences))].sort((a,b)=>a-b).map(v=>{let a=d.filter(r=>r.absences===v);return[v,a.length,f(mean(a.map(r=>r.G3)))]}))}
function heat(d){let s='<text x="160" y="20">Father’s education →</text>',rows=[];for(let m=0;m<5;m++){s+=`<text x="8" y="${62+m*40}">Mother: ${m}</text>`;for(let p=0;p<5;p++){let a=d.filter(r=>r.Medu===m&&r.Fedu===p),n=a.length,v=n?mean(a.map(r=>r.G3)):0,x=90+p*80,yy=35+m*40;s+=`<rect x="${x}" y="${yy}" width="76" height="36" rx="3" fill="${n<10?'#e9ede7':`hsl(145 30% ${95-v*2.5}%)`}"/><text x="${x+38}" y="${yy+22}" text-anchor="middle">${n<10?'—':f(v)}</text>`;rows.push([m,p,n,n<10?'Suppressed':f(v)])}}return card('04 · How does parental education relate to achievement?',svg(s),'Mean grades; cells with n < 10 are suppressed. Education codes: 0 none, 1 primary, 2 lower secondary, 3 secondary, 4 higher education.',['Mother code','Father code','n','Mean'],rows)}
function render(){let school=$('#school').value,d=DATA.records.filter(r=>school==='all'||r.school===school);$('#stats').innerHTML=[[d.length,'Student records'],[f(mean(d.map(r=>r.G3))),'Mean final grade / 20'],[new Set(d.map(r=>r.school)).size,'Schools represented'],['6','Research questions']].map(([v,l])=>`<div class="stat"><strong>${v}</strong><span>${l}</span></div>`).join('');$('#insight').textContent='Read the distribution, not just the average. Study-time groups differ in size; higher-education plans and support needs may reflect prior achievement. All comparisons below are exploratory associations.';$('#charts').innerHTML=box(d,'studytime','01 · Do students who study more achieve higher grades?','Study time is an ordered category, not an exact count of hours.')+scatter(d)+comparison(d,['internet'],'03 · Do grades differ by home internet access?','Means with 95% intervals. Access may also reflect household resources.')+heat(d)+box(d,'higher','05 · Do higher-education plans align with different outcomes?','Aspirations and achievement can influence each other; direction is not established.')+comparison(d,['schoolsup','famsup'],'06 · How do outcomes differ by educational support?','School and family support are separate comparisons. Students can belong to both groups. Differences do not measure programme effectiveness.')}
fetch('data/analysis.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}).then(d=>{DATA=d;render();$('#school').onchange=render;$('#reset').onclick=()=>{$('#school').value='all';render()};$('#regression').innerHTML=table(['Adjusted term','Grade difference','95% CI'],d.coefficients.map(c=>[c.term,f(c.estimate),`${f(c.low)} to ${f(c.high)}`]));$('#models').innerHTML='<p>Full dataset only. Five shuffled folds (seed 42), identical splits for both models. Error is measured in grade points; lower is better. No G1/G2 or absences are used. Preprocessing is fitted inside each fold. Ridge α=10 was fixed in advance; no tuning on evaluation folds. Random folds measure within-sample performance, not generalisation to new schools.</p>'+table(['Model','Mean absolute error','Per-fold MAE'],Object.entries(d.models).map(([k,v])=>[k,f(v.mae),v.fold_mae.map(f).join(' · ')]));$('#quality').textContent=`Data checks: ${d.missing} missing cells; ${d.duplicate_rows} exactly duplicated rows. All 649 grades pass the 0–20 range check. Source SHA-256: ${d.sha256}.`;}).catch(e=>{$('#insight').textContent='Analysis could not load. Please reload the page.';console.error(e)});
